mapper.select:
SELECT	MAX(cr_ver) AS lstver
FROM	CMR0025
WHERE	cr_itemid = #{itemid}

	select b.cr_file
	from cmr0020 a, cmr0026 b
	where a.cr_itemid = #{CR_ITEMID}
	and a.cr_itemid = b.cr_itemid
	and b.cr_ver = #{CR_VER}
    and b.cr_basever = #{CR_BEFVER}

mapper.insert:
insert into cmr0020 (CR_ITEMID,CR_SYSCD,CR_DSNCD,CR_RSRCNAME, CR_RSRCCD,CR_JOBCD,CR_LANGCD,CR_STATUS,CR_CREATOR,CR_STORY, CR_OPENDATE,CR_LASTDATE,CR_LSTVER,CR_EDITOR,CR_NOMODIFY, CR_PGMTYPE, CR_LSTUSR, CR_LSTDAT,CR_TESTVER,CR_TESTSTA,CR_REALVER,CR_REALSTA ,CR_ISRID ) values (lpad(ITEMID_SEQ.NEXTVAL,12,'0'),#{CR_SYSCD},#{CR_DSNCD},#{CR_RSRCNAME},CHGRSRC(#{CR_SYSCD},#{CR_RSRCNAME},#{CR_RSRCCD}), #{CR_JOBCD},#{CR_LANGCD},'3',#{CR_CREATOR},nvl(#{CR_STORY},'일괄등록'),sysdate,sysdate, 0,#{CR_EDITOR},'0',#{CR_PGMTYPE}, #{CR_LSTUSR}, sysdate,'0','0',0,'0'
,#{CR_ISRID}
,''
)

mapper.select:
select a.cr_itemid,a.cr_rsrcname,a.cr_lstver, a.cr_editor, (select cm_username from cmm0040 where cm_userid=a.cr_editor) as editorname, to_char(a.cr_lastdate,'yyyy/mm/dd/hh24/mi/ss') as lastdate, a.cr_status, nvl(g.cm_dirpath,'/') as dirpath, l.cm_jobname, i.cm_codename sta, a.cr_rsrccd, e.cm_codename jawon, a.cr_jobcd, a.cr_lstusr, (select cm_username from cmm0040 where cm_userid=nvl(a.cr_lstusr,a.cr_editor)) as lstusrname, d.cr_md5sum, a.cr_tstver cr_tstver, '' cr_tstmd5, c.cm_syscd, c.cm_sysmsg, j.cm_info, c.cm_prjname, a.cr_isrid, a.cr_viewver from cmm0036 j,cmm0070 g,cmm0020 i,cmm0102 l,cmr0025 d, cmm0020 e,cmm0030 c,cmm0038 f,cmr0020 a, cmm0031 h where a.cr_itemid=d.cr_itemid(+)
and a.cr_syscd=#{syscd}
and a.cr_itemid in (select cr_itemid from cmr1010 where instr(#{acptno},cr_acptno)>0)
and a.cr_itemid = #{itemid}
and a.cr_rsrcname = #{filename}
and g.cm_dirpath = h.cm_volpath||decode(substr(c.cm_sysinfo,16,1),'1','/'||l.cm_deptcd,'')|| decode(#{filepath}, '/', '', #{filepath})
and g.cm_dirpath like h.cm_volpath||decode(substr(c.cm_sysinfo,16,1),'1','/'||l.cm_deptcd,'')|| decode(#{dirpath}, '/', '', #{dirpath}) ||'%'
and a.cr_lstver=d.cr_ver(+) and a.cr_syscd=g.cm_syscd and a.cr_dsncd=g.cm_dsncd and a.cr_syscd=j.cm_syscd and a.cr_syscd=c.cm_syscd and j.cm_syscd=a.cr_syscd and j.cm_closedt is null and a.cr_syscd=f.cm_syscd and a.cr_rsrccd = f.cm_rsrccd and f.cm_rsrccd=j.cm_rsrccd and f.cm_svrcd=c.cm_dirbase and f.cm_svrcd=h.cm_svrcd and f.cm_seqno=h.cm_seqno and c.cm_syscd= h.cm_syscd and h.cm_closedt is null and h.cm_svrcd = c.cm_dirbase
and a.cr_rsrccd in
#{item}
and e.cm_macode='JAWON' and a.cr_rsrccd=e.cm_micode
and e.cm_codename = #{jawon}
and i.cm_macode='CMR0020' and a.cr_status=i.cm_micode and a.cr_jobcd=l.cm_jobcd
and a.cr_jobcd=#{jobcd}
and substr(j.cm_info,58,1)='1' and j.cm_rsrccd not in ( select cm_samersrc from cmm0037 where cm_syscd = j.cm_syscd and cm_samersrc is not null )

select * from (select row_number()over(order by cr_rsrcname,nvl(g.cm_dirpath,'/') desc) as num, a.cr_itemid,a.cr_rsrcname,a.cr_lstver, a.cr_editor, (select cm_username from cmm0040 where cm_userid=a.cr_editor) as editorname, to_char(a.cr_lastdate,'yyyy/mm/dd/hh24/mi/ss') as lastdate, a.cr_status, nvl(g.cm_dirpath,'/') as dirpath, l.cm_jobname, i.cm_codename sta, a.cr_rsrccd, e.cm_codename jawon, a.cr_jobcd, a.cr_lstusr, (select cm_username from cmm0040 where cm_userid=nvl(a.cr_lstusr,a.cr_editor)) as lstusrname, d.cr_md5sum, a.cr_tstver cr_tstver, '' cr_tstmd5, c.cm_syscd, c.cm_sysmsg, j.cm_info, c.cm_prjname, a.cr_viewver from cmm0036 j,cmm0070 g,cmm0020 i,cmm0102 l,cmr0025 d, cmm0020 e,cmm0030 c,cmr0020 a where a.cr_syscd=#{syscd}
and a.cr_jobcd in (select cm_jobcd from cmm0044 where cm_syscd = a.cr_syscd and cm_userid = #{userid})
and a.cr_jobcd=#{jobcd}
and a.cr_status != '9' and a.cr_itemid=d.cr_itemid(+) and a.cr_lstver=d.cr_ver(+) and a.cr_syscd=g.cm_syscd and a.cr_dsncd=g.cm_dsncd and a.cr_syscd=j.cm_syscd and a.cr_rsrccd=j.cm_rsrccd and a.cr_syscd=c.cm_syscd and j.cm_syscd=a.cr_syscd and e.cm_macode='JAWON' and a.cr_rsrccd=e.cm_micode and i.cm_macode='CMR0020' and a.cr_status=i.cm_micode and a.cr_jobcd=l.cm_jobcd and substr(j.cm_info,58,1)='1' and j.cm_rsrccd not in ( select cm_samersrc from cmm0037 where cm_syscd = j.cm_syscd and cm_samersrc is not null ) ) where num between #{start} and #{end}

select count(a.cr_itemid) from cmm0036 j,cmm0070 g,cmm0020 i,cmm0102 l,cmr0025 d, cmm0020 e,cmm0030 c,cmr0020 a where a.cr_syscd=#{syscd}
and a.cr_jobcd in (select cm_jobcd from cmm0044 where cm_syscd = a.cr_syscd and cm_userid = #{userid})
and a.cr_jobcd=#{jobcd}
and a.cr_status != '9' and a.cr_itemid=d.cr_itemid(+) and a.cr_lstver=d.cr_ver(+) and a.cr_syscd=g.cm_syscd and a.cr_dsncd=g.cm_dsncd and a.cr_syscd=j.cm_syscd and a.cr_syscd=c.cm_syscd and j.cm_syscd=a.cr_syscd and j.cm_rsrccd=a.cr_rsrccd and e.cm_macode='JAWON' and a.cr_rsrccd=e.cm_micode and i.cm_macode='CMR0020' and a.cr_status=i.cm_micode and a.cr_jobcd=l.cm_jobcd and substr(j.cm_info,58,1)='1' and j.cm_rsrccd not in ( select cm_samersrc from cmm0037 where cm_syscd = j.cm_syscd and cm_samersrc is not null )

select cr_itemid from cmr0020
where cr_syscd = #{cr_syscd}
and cr_dsncd = #{cr_dsncd}
and upper(cr_rsrcname) = #{cr_rsrcname}

mapper.update:
update cmr0020
set CR_STATUS = #{SET_CR_STATUS},
    CR_EDITOR = #{SET_CR_EDITOR}

    ,CR_ISRID = #{SET_CR_ISRID}


	,CR_LASTDATE=SYSDATE



	,CR_CKOUTUSER=#{SET_CR_CKOUTUSER}


	,CR_CKOUTACPT=#{SET_CR_CKOUTACPT}



	,CR_EDITVER=#{SET_CR_EDITVER}


where CR_ITEMID = #{PARAM_CR_ITEMID}
